examples.template:
MonarchAiAgentPicker(
    selection: $agent,
    agents: [
        MonarchAiAgentPickerOption(
            MonarchAiAgentRef(id: {{agents.0.id}}, name: {{agents.0.name}}, role: {{agents.0.role}}),
            description: {{agents.0.description}},
            capabilities: [{{agents.0.capabilities.0}}, {{agents.0.capabilities.1}}],
            tools: [MonarchAiAgentTool({{agents.0.tools.0}}), MonarchAiAgentTool({{agents.0.tools.1}})]
        ),
        MonarchAiAgentPickerOption(
            MonarchAiAgentRef(id: {{agents.1.id}}, name: {{agents.1.name}}, role: {{agents.1.role}}),
            description: {{agents.1.description}},
            capabilities: [{{agents.1.capabilities.0}}, {{agents.1.capabilities.1}}],
            tools: [MonarchAiAgentTool({{agents.1.tools.0}})],
            state: {{agents.1.state|case}}
        ),
        MonarchAiAgentPickerOption(
            MonarchAiAgentRef(id: {{agents.2.id}}, name: {{agents.2.name}}, role: {{agents.2.role}}),
            description: {{agents.2.description}},
            isDisabled: {{agents.2.disabled}}
        ),
    ]
)
